parameters.jsCode:
// Normalize payload
const body = $input.first().json.body || $input.first().json;
const lead = body.lead || {};
const prediction = body.prediction || {};

// Generate Lead ID
const leadId = 'ABS-' + Date.now().toString().slice(-8);

// Format college list for messaging
const topColleges = (prediction.top_colleges || []).slice(0, 5);
const collegeListText = topColleges.map((c, i) => `${i+1}. ${c.name} (${c.tier}) — Cutoff: ${c.cutoff}, Margin: ${c.delta >= 0 ? '+' : ''}${c.delta}`).join('\n');

return [{
  json: {
    leadId,
    lead,
    prediction,
    collegeListText,
    timestamp: new Date().toISOString(),
    studentMobile: '91' + String(lead.mobile || '').replace(/^91/, ''),
    counselorMobiles: ['919702836946', '919702836946'],
    safeCount: prediction.match_counts?.safe || 0,
    moderateCount: prediction.match_counts?.moderate || 0,
    reachCount: prediction.match_counts?.reach || 0,
    top3Names: topColleges.slice(0, 3).map(c => c.name + ' (' + c.tier + ')').join(' | ')
  }
}];

